using StrataLint.Scribe;
using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum;
internal sealed class GleasonComplexRepresentationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Finite complex projection Gleason representation", H("Finite complex projection Gleason representation"), Blocks(
            Describe.Lean(DescribeId.Create("main-result"),
                DeclarationHandle.Create("D5/S3/Quantum/GleasonComplexRepresentation.gleason_representation"),
                H("Finite complex projection Gleason representation"), StatementSource.FromAuthor(Disp(MainFormula())),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/gleason1957measures")),
                Blocks(Paragraph(Text("Gleason (1957), J. Math. Mech. 6, 885–893, supplies Lemma 3.4 (two-dimensional restrictions to a global bounded form), Theorem 3.5 (nonnegative frame-function regularity in dimension at least three), and Theorem 4.1 (closed-subspace measure trace-class representation). The adopted elementary real core (Sphere through General) follows Cooke, Keane, Moran (1985), Math. Proc. Cambridge Philos. Soc. 98, 117–128.")),
                    Paragraph(Text("For every natural dimension N at least three and every projection package OP on complex N by N matrices, there is exactly one matrix rho that is positive semidefinite, has trace one, and satisfies OP.p(P) = Re(trace(rho P)) for every star projection P. The package is a total matrix function, constrained only by nonnegative projection values, normalization at the identity and binary additivity on orthogonal star projections.")),
                    Paragraph(Text("Restrict the rank-one frame function to every completely real orthonormal triple. The real sphere theorem gives a quadratic restriction there. Extending each real orthonormal pair to such a triple gives real-plane regularity. Comparing rotated pairs shows the cross term depends linearly on the real and imaginary parts of a unit phase.")),
                    Paragraph(Text("The homogeneous extension of the frame function to all vectors satisfies the parallelogram law. Integer quadratic polarization and bounded additive real linearity yield a sesquilinear form. Its standard-basis matrix is Hermitian and has the original function as its diagonal quadratic form. Mixed real scalar identities are derived in this construction, rather than assumed.")),
                    Paragraph(Text("Sphere positivity gives positive semidefiniteness, and the standard orthonormal frame sum gives trace one. Spectral resolution of a star projection has eigenvalues zero or one, so finite orthogonal additivity extends the rank-one formula to every projection. Equality on all rank-one projections determines the matrix, proving uniqueness.")),
                    Paragraph(Text("Projective noncontextuality and the all-projections domain are mathematical premises. The theorem does not derive them empirically. Its displayed statement and Lean declaration concern finite complex matrices."))), DescribeRole.Theorem),
            new DocumentBlock.Section(H("Application to a countably additive projection measure"), Blocks(
            Paragraph(Text("Let H be a complete separable complex Hilbert space containing an orthonormal triple, and write Op = H →L[C] H. Finite-dimensional H is included. Let p : Op → R be a total function whose values on star projections are nonnegative and whose value at the identity is one. Assume the following exact countable law: for every star projection P and every sequence of star projections Q_i with Q_i Q_j = 0 whenever i differs from j, if, for every x in H, the sums of Q_i x over i < n converge to Px, then HasSum (i ↦ p(Q_i)) (p(P)). Only the values of p on projections enter the argument; its values elsewhere are unrestricted.")),
            Paragraph(Text("These assumptions jointly give one positive continuous complex-linear functional phi : Op →L[C] C with phi(1) = 1, norm phi = 1 and phi(P) = p(P), viewed as a complex number, for every star projection P; one sequence E_n of finite-rank star projections with E_n x tending to x for every x and Re(phi(1 − E_n)) tending to zero; and one positive operator rho : Op with a native certificate h_rho : IsTraceClass rho. Its analytic complex trace is trace rho h_rho = 1. For every bounded operator A there is a native certificate h_rho_A : IsTraceClass (rho * A) and phi(A) = trace (rho * A) h_rho_A. Every positive native trace-class trace-one operator sigma whose real trace pairing on projections equals the original p equals this same rho. All these clauses hold for the same phi, E and rho. This is an application of the existing finite Gleason, positive extension, Hilbert basis, vector-series and analytic trace suppliers; it introduces no additional Lean declaration or theorem Describe.")),
            Paragraph(Text("First, the countable law applied to the zero sequence gives p(0) = 0. Applying it to P, Q, 0, 0, ... gives binary orthogonal additivity. Consequently p(P) + p(1 − P) = 1 for every star projection P, and every such value lies between zero and one. These consequences use the stated countable law directly; continuity of the total function p is not assumed.")),
            Paragraph(Text("To obtain the norm estimate needed for linear extension, fix any finite list P_i of finite-rank star projections, arbitrary real coefficients a_i and a real a_0. The list need not commute and may be empty. Take U to be the sum of their ranges and the span of the chosen orthonormal triple. This is a finite-dimensional subspace of dimension N at least three. An orthonormal coordinate isometry J : C^N → H identifies U with a matrix corner through F(A) = J A J*, and E = F(1) is its support projection. Each P_i is supported by E, so E P_i = P_i E = P_i and the coordinate matrix M_i = J* P_i J is a star projection. This supported compression is the only projection compression used here.")),
            Paragraph(Text("The function q(A) = p(F(A)) is nonnegative and orthogonally additive on matrix projections, with actual corner mass m = q(1) = p(E) in [0,1]. If m is positive, q/m is a normalized projection package, so Gleason.ProjectionPackage.gleason_representation supplies a positive matrix which, after scaling by m, gives a positive semidefinite rho with trace rho = m and q(A) = Re(trace(rho A)) on every matrix projection A. If m = 0, additivity and nonnegativity applied to A and 1 − A give q(A) = 0; rho = 0 then supplies the same formula without division.")),
            Paragraph(Text("Set T = a_0 I + sum_i a_i P_i and B = a_0 I_N + sum_i a_i M_i. Then B = J* T J in coordinates, so norm B is at most norm T, and Re(trace(B rho)) = a_0 m + sum_i a_i p(P_i). The existing re_trace_mul_le estimate in "), Ref("D5/S3/Quantum/Matrix/UniformVarianceTraceBound"), Text(" applied to B and −B bounds the absolute value of this real trace by (norm B)(traceNorm rho). The identity traceNorm_of_posSemidef in "), Ref("D5/S3/Quantum/Foundation/FiniteTraceDistance"), Text(" identifies traceNorm rho with m. Thus |a_0 m + sum_i a_i p(P_i)| is at most (norm T)m.")),
            Paragraph(Text("The complementary mass must also be accounted for. When E differs from I, T(I − E) = a_0(I − E), and the operator norm product inequality, divided by the strictly positive norm of I − E, gives |a_0| at most norm T. Adding the bound for a_0(1 − m) yields |a_0 + sum_i a_i p(P_i)| at most norm T. When E = I, m = 1 and the trace estimate already gives this result. The argument therefore retains the zero-mass corner, full-support corner, empty list and finite-dimensional ambient cases.")),
            Paragraph(Text("Let S be the set of finite-rank star projections and X the real span of {I} union S inside Op. On formal finite combinations define g(a_0,c) = a_0 I + sum_P c(P)P and q(a_0,c) = a_0 + sum_P c(P)p(P), with c finitely supported on S. The preceding inequality gives |q(d)| at most norm(g(d)) for every formal combination d. In particular g(d) = 0 forces q(d) = 0, so q descends consistently to a real continuous functional f on X. The pinned LinearMap.compLeftInverse interface implements this descent, with compLeftInverse_apply_of_bdd giving its value on each formal combination. The resulting functional has norm at most one, f(I) = 1 and f(P) = p(P) for every P in S. Since the orthonormal triple makes H nontrivial and norm I = 1, norm f is exactly one.")),
            Paragraph(Text("Every element of X is selfadjoint. Apply exists_positive_extensions_norm_additive from "), Ref("D5/S3/Quantum/Algebra/CentralPositiveFunctionalExtension"), Text(" to X and f. It gives positive complex functionals plus and minus whose difference of real parts restricts to f, with Re(plus(I)) + Re(minus(I)) = norm f = 1. At I their difference is also f(I) = 1. Positivity therefore forces Re(minus(I)) = 0 and Re(plus(I)) = 1. PositiveContinuousLinearMap.ofReal_opNorm_eq_map_one gives norm minus = 0, hence minus vanishes. Taking phi = plus gives a positive continuous complex-linear functional with phi(I) = 1 and norm phi = 1. Positive functionals take real values on selfadjoint elements, so phi restricts to the real functional f on X, including every finite-rank star projection.")),
            Paragraph(Text("To reach an arbitrary star projection P, use a countable orthonormal basis of its closed range. The private CountableBasisPort.exists_countable_hilbertBasis supplier in "), Ref("D5/S3/Observer/HilbertGeometry/HilbertPathFundamentalTheorem"), Text(" already provides this basis for complete separable real or complex Hilbert spaces, with Lean's lawful open private visibility from that source module. Inject its index type into the natural numbers and extend the associated rank-one projections by zero outside the injection's range. This gives a sequence Q_i of mutually orthogonal finite-rank star projections. HilbertBasis.hasSum_orthogonalProjectionOnto, together with hasSum_extend_zero, gives HasSum (i ↦ Q_i x) (Px) for each vector x. An injection with zero extension handles finite bases and the empty basis as well; no equivalence between the basis index and all natural numbers is needed.")),
            Paragraph(Text("Write S_n = sum_{i<n} Q_i. The vectorwise sum and uniqueness of sums imply Q_i P = Q_i, so P − S_n is a star projection. Positivity of phi and its finite-rank agreement give sum_{i<n} p(Q_i) = Re(phi(S_n)) at most Re(phi(P)). The raw countable law makes these scalar partial sums tend to p(P), proving p(P) at most Re(phi(P)). Apply the same argument to I − P. Together with p(P) + p(I − P) = 1 and phi(I) = 1, it gives the reverse inequality. Finally positivity makes the imaginary part of phi(P) zero, yielding phi(P) = p(P) as a complex equality for every star projection. The functional phi is the same one constructed from f; it is not chosen separately for different projections.")),
            Paragraph(Text("Apply the basis construction to I and set E_n = sum_{i<n} Q_i for that decomposition. Each E_n is a star projection with finite-dimensional range, and its vectorwise convergence to I is the basis expansion. The countable law at I gives sum_{i<n} p(Q_i) tending to one. Linearity and projection agreement for the same phi give Re(phi(I − E_n)) = 1 − sum_{i<n} p(Q_i), which tends to zero. Strong operator convergence is used only in the raw countable law and the basis expansion; it is not converted to operator norm convergence.")),
            Paragraph(Text("Now apply D5.S3.Quantum.Analysis.TightStateVectorSeries.positive_functional_vector_series_of_finite_rank_tightness in "), Ref("D5/S3/Quantum/Analysis/TightStateVectorSeries"), Text(" to this same H and phi, viewing phi as a positive linear map Op →ₚ[C] C. Its parameter hφone is phi(1) = 1; its E, hE and hEfinite are exactly the sequence, star-projection proofs and finite-dimensional range proofs just obtained; and its htight is exactly Re(phi(1 − E_n)) tending to zero. The supplier needs no operator norm convergence of E_n. It yields one family u : Nat → H with HasSum (k ↦ norm(u_k)^2) 1 and, simultaneously for every A : Op, HasSum (k ↦ ⟨u_k, A u_k⟩) (phi(A)). These are respectively real and complex sums. The supplier's conclusion is this vector family and these sums; construction of a native density, its trace-class proof and uniqueness require the following additional steps.")),
            Paragraph(Text("Use the complex inner product conjugate-linear in its first argument, and write R(w,v) = rankOne C w v for the operator x ↦ ⟨v,x⟩ w. Define the bounded sesquilinear form B(v,w) = phi(R(w,v)). The norm estimate norm(phi) = 1 and norm(R(w,v)) ≤ norm(w) norm(v) bound B by norm(v) norm(w). InnerProductSpace.continuousLinearMapOfBilin in pinned Mathlib.Analysis.InnerProductSpace.Dual gives rho : Op; continuousLinearMapOfBilin_apply gives ⟨rho v,w⟩ = B(v,w). The vector-series formula at R(w,v) identifies B(v,w) with sum_k ⟨v,u_k⟩⟨u_k,w⟩. These terms are absolutely summable, bounded in norm by norm(v) norm(w) norm(u_k)^2. Thus B is Hermitian, rho is selfadjoint, and ⟨x,rho x⟩ = sum_k |⟨u_k,x⟩|^2 is a nonnegative real number. This proves 0 ≤ rho and also gives ⟨v,rho w⟩ = sum_k ⟨v,u_k⟩⟨u_k,w⟩. Here rho is an operator on H; the earlier corner matrices act on their finite coordinate spaces.")),
            Paragraph(Text("The native notions used here are the root-level IsTraceClass and trace from "), Ref("D5/S3/Quantum/Analysis/TraceClass/Basic"), Text(". Explicitly, IsTraceClass T means that for some HilbertBasis b : HilbertBasis w C H the real family i ↦ Re⟨b_i, (CFC.abs T)b_i⟩ is summable. The value trace T h_T is the complex diagonal sum in the basis witnessing h_T. Choose a Hilbert basis b of H using the same countable-basis supplier; its index set may be finite. Since rho is positive, CFC.abs_of_nonneg gives CFC.abs rho = rho. Its diagonal is Re⟨b_i,rho b_i⟩ = sum_k |⟨u_k,b_i⟩|^2. For every finite set of basis indices the diagonal sum is at most sum_k norm(u_k)^2 = 1, by Parseval and nonnegativity. The pinned summable_of_sum_le therefore supplies the real summability required by the actual native predicate, giving h_rho : IsTraceClass rho.")),
            Paragraph(Text("The Parseval supplier hasSum_norm_sq_inner_basis in that same Basic source, conjugate symmetry of the inner product, and summable_prod_of_nonneg justify the nonnegative double sum. Its total mass is sum_i sum_k |⟨u_k,b_i⟩|^2 = sum_k sum_i |⟨u_k,b_i⟩|^2 = sum_k norm(u_k)^2 = 1. Consequently the complex diagonal sum of rho is the complex number 1. This is analytic trace normalization for the native predicate, rather than a finite-matrix trace or a definition assigning rho a chosen trace.")),
            Paragraph(Text("Native certificates for products come from isTraceClass_mul_mul in "), Ref("D5/S3/Quantum/Analysis/TraceClass/GeneralProduct"), Text(". Its exact conclusion from h_T : IsTraceClass T is IsTraceClass (L * T * R) for arbitrary bounded L and R. In particular h_rho_A is obtained from isTraceClass_mul_mul (A := 1) (B := A) h_rho by simplifying 1 * rho * A to rho * A. For any competitor h_sigma : IsTraceClass sigma, the same formula with (A := 1) (B := P) h_sigma gives h_sigma_P : IsTraceClass (sigma * P). Positivity of these products is not required. The arbitrary-operator trace_eq_of_hilbertBasis in "), Ref("D5/S3/Quantum/Analysis/TraceClass/GeneralIdeal"), Text(" evaluates each such native trace as sum_i ⟨b_i,T b_i⟩, including when T = rho * A is not selfadjoint. A positive-only trace formula would not cover this step.")),
            Paragraph(Text("For the interchange needed at an arbitrary A, the kernel formula gives ⟨b_i,rho(A b_i)⟩ = sum_k ⟨b_i,u_k⟩⟨u_k,A b_i⟩. Rewrite the second factor using A's adjoint. HilbertSchmidt.summable_norm_mul_of_square_sums and HilbertSchmidt.tsum_norm_inner_mul_inner_le in "), Ref("D5/S3/Quantum/Analysis/TraceClass/HilbertSchmidt"), Text(" apply to the basis coefficients of A* u_k and u_k: their square sums are finite by hasSum_norm_sq_inner_basis, and sum_i |⟨b_i,u_k⟩| |⟨u_k,A b_i⟩| ≤ norm(A* u_k) norm(u_k) ≤ norm(A) norm(u_k)^2. The outer bound is summable by the real vector-mass identity. Applying summable_prod_of_nonneg to the family of term norms proves absolute summability over both indices, so Summable.tsum_comm legitimately exchanges the complex sums. No interchange is inferred merely from pointwise convergence.")),
            Paragraph(Text("After this exchange, HilbertBasis.hasSum_inner_mul_inner in pinned Mathlib.Analysis.InnerProductSpace.l2Space evaluates the inner basis sum as ⟨A* u_k,u_k⟩ = ⟨u_k,A u_k⟩. Thus trace (rho * A) h_rho_A = sum_i sum_k ⟨b_i,u_k⟩⟨u_k,A b_i⟩ = sum_k ⟨u_k,A u_k⟩ = phi(A) for every bounded complex-linear A. Taking A = I recovers trace rho h_rho = phi(I) = 1, consistently with the diagonal mass calculation. Taking A = P and using the original projection agreement gives p(P) = Re(trace (rho * P) h_rho_P) for every star projection. The equality on all A pairs rho with the same complex phi; it imposes no condition on raw p(A) at nonprojections.")),
            Paragraph(Text("For uniqueness, let sigma : Op have h_sigma : IsTraceClass sigma, 0 ≤ sigma, trace sigma h_sigma = 1, and only the original projection readings p(P) = Re(trace (sigma * P) h_sigma_P) for every star projection P. The native product certificates above are available automatically. For any native trace-class T and unit vector e, trace_eq_of_hilbertBasis and HilbertBasis.hasSum_inner_mul_inner give trace (T * R(e,e)) h_T_R = sum_i ⟨e,b_i⟩⟨b_i,T e⟩ = ⟨e,T e⟩. The operator R(e,e) is a star projection. Applying this evaluation to sigma and rho shows that Re⟨e,sigma e⟩ and Re⟨e,rho e⟩ are both p(R(e,e)). Positivity makes both quadratic forms real, so their equality is a complex equality as well.")),
            Paragraph(Text("For x = 0 both quadratic forms vanish. For x nonzero, take e = (norm(x)⁻¹ : C) • x, so norm(e) = 1 and x = (norm(x) : C) • e. Sesquilinearity gives ⟨sigma x,x⟩ = (norm(x)^2 : C) (p(R(e,e)) : C) = ⟨rho x,x⟩, using positivity to identify either inner-product orientation on the diagonal. Hence the original rank-one projection readings determine the quadratic form on every vector, including zero. The pinned ext_inner_map in Mathlib.Analysis.InnerProductSpace.LinearMap, applied to sigma.toLinearMap and rho.toLinearMap, converts this equality of complex quadratic forms into sigma = rho. The competitor is not supplied with agreement on all bounded operators or agreement with phi; these are not uniqueness premises.")),
            Paragraph(Text("The vector family u is auxiliary and need not be unique. The positive native trace-class density rho is unique under the stated projection readings, and its all-operator pairing is with the already constructed phi. The sequence E and its tightness remain those derived from the raw projection law. The construction is a composition of existing results within the classical Gleason representation, with no claim of new mathematical content or literature novelty.")),
            Paragraph(Text("The application requires the orthonormal triple, separability and the exact countable projection law. It includes finite-dimensional H, finite and empty range bases, zero vectors, zero-mass corners and full-support corners. It assumes no continuity or measurability of raw p, no additivity on arbitrary effects, and no supplied functional, exhaustion, density, normality or tightness premise. The complex result here does not assert the dimension-two case or transfer its complex polarization argument to a real Hilbert space; the real Gleason setting requires its corresponding real statement. Projective noncontextuality and the domain of all projections remain mathematical premises rather than empirical conclusions, and the construction makes no new physical claim. The finite theorem Describe, its displayed matrix formula and its truth anchor retain their original meaning.")))))));
    private static Formula MainFormula() => All(Imp(LE(Num(3), X("N")), Ex(And(Law(X("rho")), All(Imp(Law(X("sigma")), Eq(X("sigma"), X("rho"))), ("sigma", Mat()))), ("rho", Mat()))), ("N", X("Nat")), ("OP", C("ProjectionPackage", X("N"))));

    private static Formula X(string x) => DefinitionDsl.Id(x);
    private static Formula C(string f, params Formula[] xs) => DefinitionDsl.Call(f, xs);
    private static Formula Eq(Formula a, Formula b) => DefinitionDsl.Equal(a, b);
    private static Formula LE(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThanOrEqual, b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.And, b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Implies, b);
    private static Formula All(Formula body, params (string Name, Formula Type)[] xs)
    {
        for (var i = xs.Length - 1; i >= 0; --i)
            body = new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(xs[i].Name), xs[i].Type, body);
        return body;
    }
    private static Formula Ex(Formula body, params (string Name, Formula Type)[] xs)
    {
        for (var i = xs.Length - 1; i >= 0; --i)
            body = new Formula.Bind(FormulaQuantifier.Exists, FormulaIdentifier.Create(xs[i].Name), xs[i].Type, body);
        return body;
    }
    private static Formula Mat() => C("Matrix", C("Fin", X("N")), C("Fin", X("N")), X("C"));
    private static Formula Law(Formula rho) => And(C("PosSemidef", rho), And(Eq(C("trace", rho), Num(1)), All(Imp(C("IsStarProjection", X("P")), Eq(C("p", X("OP"), X("P")), C("Re", C("trace", Multiply(rho, X("P")))))), ("P", Mat()))));
}
